// Package wordfreq counts ASCII-letter words and ranks them by frequency.
//
// A word is a maximal run of [A-Za-z], folded to lowercase. Every other byte
// is a separator.
package wordfreq

import (
	"cmp"
	"errors"
	"io"
	"slices"
)

const readChunk = 64 << 10

// WordCount is a distinct word and the number of times it occurred.
type WordCount struct {
	Word  string
	Count int
}

// Counter accumulates word frequencies.
type Counter struct {
	counts map[string]int
}

// NewCounter returns an empty Counter.
func NewCounter() *Counter {
	return &Counter{counts: make(map[string]int, 4096)}
}

func isLetter(c byte) bool {
	return (c|0x20)-'a' < 26
}

// ReadFrom counts every word in r. Words spanning read boundaries are
// handled correctly. It implements io.ReaderFrom.
func (c *Counter) ReadFrom(r io.Reader) (int64, error) {
	buf := make([]byte, readChunk)
	var pending []byte // word prefix carried over from the previous chunk
	var total int64
	for {
		n, err := r.Read(buf)
		total += int64(n)
		pending = c.scan(buf[:n], pending)
		if err != nil {
			if len(pending) > 0 {
				c.add(pending)
			}
			if errors.Is(err, io.EOF) {
				return total, nil
			}
			return total, err
		}
	}
}

// scan counts the complete words in chunk, which follows the partial word
// pending. It lowercases chunk in place and returns the new partial word.
func (c *Counter) scan(chunk, pending []byte) []byte {
	i := 0
	for i < len(chunk) {
		if !isLetter(chunk[i]) {
			if len(pending) > 0 {
				c.add(pending)
				pending = pending[:0]
			}
			i++
			continue
		}
		start := i
		for i < len(chunk) && isLetter(chunk[i]) {
			chunk[i] |= 0x20
			i++
		}
		word := chunk[start:i]
		if i < len(chunk) && len(pending) == 0 {
			c.add(word) // entirely inside this chunk: no copy needed
		} else {
			pending = append(pending, word...)
		}
	}
	return pending
}

// add records one occurrence of the lowercase word w.
func (c *Counter) add(w []byte) {
	c.counts[string(w)]++
}

// Top returns up to n words ordered by count descending, then by word in
// ascending byte order.
func (c *Counter) Top(n int) []WordCount {
	if n <= 0 {
		return nil
	}
	top := make([]WordCount, 0, n+1)
	for w, cnt := range c.counts {
		wc := WordCount{Word: w, Count: cnt}
		if len(top) == n && !ranksBefore(wc, top[n-1]) {
			continue
		}
		i, _ := slices.BinarySearchFunc(top, wc, compare)
		top = slices.Insert(top, i, wc)
		if len(top) > n {
			top = top[:n]
		}
	}
	return top
}

func compare(a, b WordCount) int {
	if c := cmp.Compare(b.Count, a.Count); c != 0 {
		return c
	}
	return cmp.Compare(a.Word, b.Word) // string order is byte order
}

func ranksBefore(a, b WordCount) bool {
	return compare(a, b) < 0
}

package wordfreq

import (
	"slices"
	"strings"
	"testing"
	"testing/iotest"
)

func count(t *testing.T, input string, chunked bool) []WordCount {
	t.Helper()
	c := NewCounter()
	r := strings.NewReader(input)
	var err error
	if chunked {
		_, err = c.ReadFrom(iotest.OneByteReader(r))
	} else {
		_, err = c.ReadFrom(r)
	}
	if err != nil {
		t.Fatalf("ReadFrom: %v", err)
	}
	return c.Top(10)
}

func TestTop(t *testing.T) {
	tests := []struct {
		name  string
		input string
		want  []WordCount
	}{
		{"empty", "", []WordCount{}},
		{"no words", "123 _' \xff\xc3(", []WordCount{}},
		{"simple", "The cat and the hat.", []WordCount{{"the", 2}, {"and", 1}, {"cat", 1}, {"hat", 1}}},
		{"folding", "Hello, hello! HELLO? world.\n", []WordCount{{"hello", 3}, {"world", 1}}},
		{"separators", "don't stop_me 4now, now-NOW", []WordCount{{"now", 3}, {"don", 1}, {"me", 1}, {"stop", 1}, {"t", 1}}},
		{"high bytes", "caf\xe9 caf", []WordCount{{"caf", 2}}},
		{"limit", "zeta eta theta iota kappa lambda mu nu xi omicron pi rho alpha beta alpha",
			[]WordCount{{"alpha", 2}, {"beta", 1}, {"eta", 1}, {"iota", 1}, {"kappa", 1}, {"lambda", 1}, {"mu", 1}, {"nu", 1}, {"omicron", 1}, {"pi", 1}}},
		{"prefix order", "ab a abc", []WordCount{{"a", 1}, {"ab", 1}, {"abc", 1}}},
	}
	for _, tt := range tests {
		for _, chunked := range []bool{false, true} {
			got := count(t, tt.input, chunked)
			if !slices.Equal(got, tt.want) {
				t.Errorf("%s (chunked=%v): got %v, want %v", tt.name, chunked, got, tt.want)
			}
		}
	}
}

func TestLongWordAcrossChunks(t *testing.T) {
	w := strings.Repeat("Ab", readChunk)
	got := count(t, w+" "+w+" x", false)
	want := []WordCount{{strings.ToLower(w), 2}, {"x", 1}}
	if !slices.Equal(got, want) {
		t.Errorf("got %d entries, want long word counted twice", len(got))
	}
}

// Command app reads standard input and prints the 10 most frequent words.
package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"

	"wordfreq/internal/wordfreq"
)

const topN = 10

func main() {
	if err := run(); err != nil {
		fmt.Fprintf(os.Stderr, "wordfreq: %v\n", err)
		os.Exit(1)
	}
}

func run() error {
	counter := wordfreq.NewCounter()
	if _, err := counter.ReadFrom(os.Stdin); err != nil {
		return fmt.Errorf("read error: %w", err)
	}

	out := bufio.NewWriter(os.Stdout)
	var line []byte
	for _, wc := range counter.Top(topN) {
		line = strconv.AppendInt(line[:0], int64(wc.Count), 10)
		line = append(line, ' ')
		line = append(line, wc.Word...)
		line = append(line, '\n')
		if _, err := out.Write(line); err != nil {
			return fmt.Errorf("write error: %w", err)
		}
	}
	if err := out.Flush(); err != nil {
		return fmt.Errorf("write error: %w", err)
	}
	return nil
}
